#include <cstdio>
#include <algorithm>
using namespace std;

typedef pair<int, int> P;
typedef long long ll;

constexpr int INF = 2000000000;

P za[100005];

int main() {
    int n, x, y;  
    scanf("%d", &n);
    int lx = INF, ly = INF, rx = -INF, ry = -INF;

    for(int i = 0; i < n; i++) {
        scanf("%d%d", &x, &y);
        za[i] = {x + y, x - y};
        lx = min(lx, za[i].first);
        rx = max(rx, za[i].first);
        ly = min(ly, za[i].second);
        ry = max(ry, za[i].second);
    }

    int ret1 = 0, ret2 = 0;
    for(int i = 0; i < n; i++) {
        const int& f = za[i].first; // use reference to avoid copy
        const int& s = za[i].second; // use reference to avoid copy
        ret1 = max(ret1, min(max(f - lx, s - ly), max(rx - f, ry - s)));
        ret2 = max(ret2, min(max(f - lx, ry - s), max(rx - f, s - ly)));
    }

    printf("%d\n", min(ret1, ret2));
}

